-- ============================================================
-- Feature 011 — PostgreSQL baseline (re-expresses SQLite migrations 001–025).
-- Fresh-install schema for the bundled PostgreSQL 17 + pgvector engine.
-- Conventions (plan/research R5, data-model):
--   * TEXT uuid ids and TEXT/BIGINT timestamps preserved 1:1 (no behavior change)
--   * every SQLite INTEGER → BIGINT (sqlx PG decodes are type-strict; code reads i64)
--   * REAL → DOUBLE PRECISION; BLOB → BYTEA; JSON-in-TEXT stays TEXT in v1
--   * SQLite AUTOINCREMENT → BIGINT GENERATED BY DEFAULT AS IDENTITY
--     (BY DEFAULT so the one-time migration can preserve source ids)
--   * FTS5 virtual tables + sync triggers → STORED tsvector generated columns + GIN
--   * chunk_embeddings is NOT here — created at runtime with the configured
--     embedding dim by schema.rs::ensure_vector_table (768/384, db_config)
-- ============================================================

CREATE EXTENSION IF NOT EXISTS vector;

-- ─── 001 core ────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS db_config (
    key   TEXT PRIMARY KEY,
    value TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS notebooks (
    id         TEXT PRIMARY KEY,
    name       TEXT NOT NULL,
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL
);

CREATE TABLE IF NOT EXISTS sources (
    id               TEXT PRIMARY KEY,
    file_path        TEXT NOT NULL UNIQUE,
    file_name        TEXT NOT NULL,
    format           TEXT NOT NULL
                     CHECK (format IN ('pdf','docx','xlsx','pptx','txt','md',
                                       'png','jpg','jpeg','gif','webp','bmp',
                                       'mp3','mp4','code','audio','video','image')),
    file_size_bytes  BIGINT NOT NULL,
    file_hash        TEXT NOT NULL,
    indexing_status  TEXT NOT NULL DEFAULT 'pending'
                     CHECK (indexing_status IN ('pending','processing','indexed','failed','unindexed')),
    error_reason     TEXT,
    last_modified    BIGINT NOT NULL,
    indexed_at       BIGINT,
    created_at       BIGINT NOT NULL,
    -- 008
    ner_status       TEXT NOT NULL DEFAULT 'done' CHECK (ner_status IN ('pending','running','done')),
    ner_progress     BIGINT NOT NULL DEFAULT 100,
    ner_total        BIGINT NOT NULL DEFAULT 0,
    -- 016
    extraction_method TEXT,
    quality_score     DOUBLE PRECISION,
    -- 017
    doc_type          TEXT,
    doc_type_source   TEXT CHECK (doc_type_source IN ('auto','llm','user')),
    structure_status  TEXT CHECK (structure_status IN ('structured','failed','skipped')),
    structure_importer_version BIGINT NOT NULL DEFAULT 0,
    -- 018
    ir_cache_sha          TEXT,
    ir_quality_score      DOUBLE PRECISION,
    nodes_low_confidence  BIGINT,
    -- 020
    index_tier        TEXT NOT NULL DEFAULT 'fast' CHECK (index_tier IN ('fast','deep'))
);
CREATE INDEX IF NOT EXISTS idx_sources_status ON sources(indexing_status);
CREATE INDEX IF NOT EXISTS idx_sources_hash   ON sources(file_hash);
CREATE INDEX IF NOT EXISTS idx_sources_ner_status ON sources(ner_status);
CREATE INDEX IF NOT EXISTS idx_sources_structure_version ON sources(structure_importer_version);
CREATE INDEX IF NOT EXISTS idx_sources_ir_cache_sha ON sources(ir_cache_sha);

CREATE TABLE IF NOT EXISTS notebook_sources (
    notebook_id TEXT NOT NULL REFERENCES notebooks(id) ON DELETE CASCADE,
    source_id   TEXT NOT NULL REFERENCES sources(id)   ON DELETE CASCADE,
    added_at    BIGINT NOT NULL,
    PRIMARY KEY (notebook_id, source_id)
);
CREATE INDEX IF NOT EXISTS idx_notebook_sources_notebook ON notebook_sources(notebook_id);
CREATE INDEX IF NOT EXISTS idx_notebook_sources_source   ON notebook_sources(source_id);

CREATE TABLE IF NOT EXISTS indexed_folders (
    id              TEXT PRIMARY KEY,
    folder_path     TEXT NOT NULL UNIQUE,
    indexing_status TEXT NOT NULL DEFAULT 'pending'
                    CHECK (indexing_status IN ('pending','scanning','processing','indexed','partial')),
    file_count      BIGINT NOT NULL DEFAULT 0,
    last_scanned_at BIGINT,
    created_at      BIGINT NOT NULL
);

CREATE TABLE IF NOT EXISTS chunks (
    id          TEXT PRIMARY KEY,
    source_id   TEXT NOT NULL REFERENCES sources(id) ON DELETE CASCADE,
    chunk_index BIGINT NOT NULL,
    content     TEXT NOT NULL,
    char_start  BIGINT NOT NULL,
    char_end    BIGINT NOT NULL,
    page_number BIGINT,
    token_count BIGINT NOT NULL,
    created_at  BIGINT NOT NULL,
    -- 013
    parent_chunk_id TEXT REFERENCES chunks(id),
    unit_type       TEXT NOT NULL DEFAULT 'leaf'
                    CHECK (unit_type IN ('document','part','chapter','article','clause','subclause','section','leaf')),
    unit_label      TEXT,
    unit_path       TEXT,
    domain_metadata TEXT,
    -- 015
    ner_pass2_done  BIGINT NOT NULL DEFAULT 0 CHECK (ner_pass2_done IN (0,1)),
    -- replaces chunks_fts (FTS5): keyword search column, auto-maintained
    tsv tsvector GENERATED ALWAYS AS (to_tsvector('english', coalesce(content,''))) STORED
);
CREATE INDEX IF NOT EXISTS idx_chunks_source     ON chunks(source_id);
CREATE INDEX IF NOT EXISTS idx_chunks_parent     ON chunks(parent_chunk_id);
CREATE INDEX IF NOT EXISTS idx_chunks_unit_type  ON chunks(unit_type);
CREATE INDEX IF NOT EXISTS idx_chunks_unit_label ON chunks(unit_label);
CREATE INDEX IF NOT EXISTS idx_chunks_ner_pass2_pending
    ON chunks(source_id, ner_pass2_done) WHERE ner_pass2_done = 0;
CREATE INDEX IF NOT EXISTS idx_chunks_tsv ON chunks USING gin (tsv);

CREATE TABLE IF NOT EXISTS query_cache (
    id              TEXT PRIMARY KEY,
    session_id      TEXT NOT NULL,
    query_text      TEXT NOT NULL,
    query_embedding BYTEA NOT NULL,
    answer_text     TEXT NOT NULL,
    citations_json  TEXT NOT NULL,
    tier_used       TEXT NOT NULL,
    created_at      BIGINT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_cache_session ON query_cache(session_id);
CREATE INDEX IF NOT EXISTS idx_cache_created ON query_cache(created_at);

CREATE TABLE IF NOT EXISTS query_sessions (
    id          TEXT PRIMARY KEY,
    notebook_id TEXT NOT NULL REFERENCES notebooks(id) ON DELETE CASCADE,
    created_at  BIGINT NOT NULL,
    updated_at  BIGINT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_sessions_notebook ON query_sessions(notebook_id);

CREATE TABLE IF NOT EXISTS query_messages (
    id             TEXT PRIMARY KEY,
    session_id     TEXT NOT NULL REFERENCES query_sessions(id) ON DELETE CASCADE,
    role           TEXT NOT NULL CHECK (role IN ('user','assistant')),
    content        TEXT NOT NULL,
    citations_json TEXT,
    tier_used      TEXT,
    created_at     BIGINT NOT NULL,
    is_incomplete  BIGINT NOT NULL DEFAULT 0          -- 005
);
CREATE INDEX IF NOT EXISTS idx_messages_session ON query_messages(session_id);

-- entities: 009 universal vocabulary
CREATE TABLE IF NOT EXISTS entities (
    id               TEXT PRIMARY KEY,
    canonical_value  TEXT NOT NULL,
    entity_type      TEXT NOT NULL
                     CHECK (entity_type IN ('person','org','location','concept','term','reference','date','amount')),
    normalized_value TEXT,
    source_count     BIGINT NOT NULL DEFAULT 0,
    created_at       BIGINT NOT NULL,
    UNIQUE(canonical_value, entity_type)
);
CREATE INDEX IF NOT EXISTS idx_entities_type  ON entities(entity_type);
CREATE INDEX IF NOT EXISTS idx_entities_value ON entities(canonical_value);

CREATE TABLE IF NOT EXISTS entity_mentions (
    entity_id    TEXT NOT NULL REFERENCES entities(id) ON DELETE CASCADE,
    chunk_id     TEXT NOT NULL REFERENCES chunks(id)   ON DELETE CASCADE,
    context_text TEXT,
    PRIMARY KEY (entity_id, chunk_id)
);
CREATE INDEX IF NOT EXISTS idx_mentions_entity ON entity_mentions(entity_id);
CREATE INDEX IF NOT EXISTS idx_mentions_chunk  ON entity_mentions(chunk_id);

CREATE TABLE IF NOT EXISTS entity_relationships (
    id                TEXT PRIMARY KEY,
    from_entity_id    TEXT NOT NULL REFERENCES entities(id) ON DELETE CASCADE,
    to_entity_id      TEXT NOT NULL REFERENCES entities(id) ON DELETE CASCADE,
    relationship_type TEXT NOT NULL,
    source_chunk_id   TEXT REFERENCES chunks(id) ON DELETE SET NULL,
    created_at        BIGINT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_rel_from ON entity_relationships(from_entity_id);
CREATE INDEX IF NOT EXISTS idx_rel_to   ON entity_relationships(to_entity_id);

CREATE TABLE IF NOT EXISTS batch_jobs (
    id                    TEXT PRIMARY KEY,
    folder_path           TEXT NOT NULL,
    operation             TEXT NOT NULL
                          CHECK (operation IN ('summarize','extract_dates','flag_keywords','extract_actions')),
    operation_params_json TEXT,
    status                TEXT NOT NULL DEFAULT 'queued'
                          CHECK (status IN ('queued','running','complete','partial')),
    total_files           BIGINT NOT NULL DEFAULT 0,
    processed_files       BIGINT NOT NULL DEFAULT 0,
    failed_files          BIGINT NOT NULL DEFAULT 0,
    created_at            BIGINT NOT NULL,
    completed_at          BIGINT
);

CREATE TABLE IF NOT EXISTS batch_results (
    id           TEXT PRIMARY KEY,
    job_id       TEXT NOT NULL REFERENCES batch_jobs(id) ON DELETE CASCADE,
    source_id    TEXT REFERENCES sources(id) ON DELETE SET NULL,
    file_path    TEXT NOT NULL,
    status       TEXT NOT NULL CHECK (status IN ('success','failed')),
    output_text  TEXT,
    error_reason TEXT,
    created_at   BIGINT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_batch_results_job ON batch_results(job_id);

CREATE TABLE IF NOT EXISTS audit_log (
    id           TEXT PRIMARY KEY,
    event_type   TEXT NOT NULL,
    entity_id    TEXT,
    details_json TEXT,
    created_at   BIGINT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_log(created_at);
CREATE INDEX IF NOT EXISTS idx_audit_event   ON audit_log(event_type);

-- ─── 004 index jobs ──────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS index_jobs (
    id              TEXT PRIMARY KEY,
    notebook_id     TEXT NOT NULL,
    root_path       TEXT NOT NULL,
    status          TEXT NOT NULL CHECK (status IN ('running','paused','cancelled','completed','failed')),
    total_files     BIGINT NOT NULL,
    processed_files BIGINT NOT NULL DEFAULT 0,
    started_at      BIGINT NOT NULL,
    updated_at      BIGINT NOT NULL,
    error           TEXT
);
CREATE INDEX IF NOT EXISTS idx_index_jobs_notebook ON index_jobs(notebook_id, status);

CREATE TABLE IF NOT EXISTS index_job_files (
    job_id          TEXT NOT NULL REFERENCES index_jobs(id) ON DELETE CASCADE,
    file_path       TEXT NOT NULL,
    mtime           BIGINT NOT NULL,
    status          TEXT NOT NULL CHECK (status IN ('pending','done','failed','skipped')),
    chunks_written  BIGINT NOT NULL DEFAULT 0,
    error           TEXT,
    PRIMARY KEY (job_id, file_path)
);
CREATE INDEX IF NOT EXISTS idx_index_job_files_status    ON index_job_files(job_id, status);
CREATE INDEX IF NOT EXISTS idx_index_job_files_path_mtime ON index_job_files(file_path, mtime, status);

-- ─── 006/007 agent tables ────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS agent_tasks (
    id             TEXT PRIMARY KEY,
    instruction    TEXT NOT NULL,
    input_mode     TEXT NOT NULL DEFAULT 'chat' CHECK (input_mode IN ('chat','voice')),
    status         TEXT NOT NULL DEFAULT 'queued'
                   CHECK (status IN ('queued','planning','awaiting_approval',
                                     'running','paused','completed','failed','cancelled')),
    queue_position BIGINT,
    result_text    TEXT,
    error_text     TEXT,
    created_at     BIGINT NOT NULL,
    updated_at     BIGINT NOT NULL,
    tsv tsvector GENERATED ALWAYS AS (to_tsvector('english', coalesce(instruction,''))) STORED
);
CREATE INDEX IF NOT EXISTS idx_agent_tasks_tsv ON agent_tasks USING gin (tsv);

CREATE TABLE IF NOT EXISTS agent_steps (
    id              TEXT PRIMARY KEY,
    task_id         TEXT NOT NULL REFERENCES agent_tasks(id) ON DELETE CASCADE,
    step_number     BIGINT NOT NULL,
    tool_name       TEXT,
    input_json      TEXT,
    output_text     TEXT,
    generated_code  TEXT,
    status          TEXT NOT NULL DEFAULT 'pending'
                    CHECK (status IN ('pending','running','completed','failed','skipped')),
    reversibility   TEXT NOT NULL DEFAULT 'reversible' CHECK (reversibility IN ('reversible','irreversible')),
    duration_ms     BIGINT,
    created_at      BIGINT NOT NULL,
    updated_at      BIGINT NOT NULL,
    tsv tsvector GENERATED ALWAYS AS (to_tsvector('english', coalesce(output_text,''))) STORED
);
CREATE INDEX IF NOT EXISTS idx_agent_steps_tsv ON agent_steps USING gin (tsv);

CREATE TABLE IF NOT EXISTS pending_actions (
    id           TEXT PRIMARY KEY,
    task_id      TEXT NOT NULL REFERENCES agent_tasks(id) ON DELETE CASCADE,
    step_id      TEXT REFERENCES agent_steps(id) ON DELETE CASCADE,
    description  TEXT NOT NULL,
    safety_class TEXT NOT NULL DEFAULT 'CAUTIOUS' CHECK (safety_class IN ('READ_ONLY','CAUTIOUS','DANGEROUS')),
    status       TEXT NOT NULL DEFAULT 'awaiting' CHECK (status IN ('awaiting','approved','rejected')),
    decided_at   BIGINT,
    created_at   BIGINT NOT NULL
);

CREATE TABLE IF NOT EXISTS execution_log (
    id          TEXT PRIMARY KEY,
    task_id     TEXT NOT NULL REFERENCES agent_tasks(id) ON DELETE CASCADE,
    step_id     TEXT REFERENCES agent_steps(id) ON DELETE CASCADE,
    event_type  TEXT NOT NULL,
    detail_json TEXT,
    created_at  BIGINT NOT NULL
);

CREATE TABLE IF NOT EXISTS rollback_log (
    id           TEXT PRIMARY KEY,
    task_id      TEXT NOT NULL REFERENCES agent_tasks(id) ON DELETE CASCADE,
    step_id      TEXT NOT NULL REFERENCES agent_steps(id) ON DELETE CASCADE,
    operation    TEXT NOT NULL,
    params_json  TEXT NOT NULL,
    undo_params  TEXT NOT NULL,
    status       TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','completed','failed','skipped')),
    created_at   BIGINT NOT NULL
);

CREATE TABLE IF NOT EXISTS agent_personas (
    id          TEXT PRIMARY KEY,
    version     TEXT NOT NULL,
    toml_path   TEXT NOT NULL,
    config_json TEXT NOT NULL,
    loaded_at   BIGINT NOT NULL
);

CREATE TABLE IF NOT EXISTS agent_settings (
    key   TEXT PRIMARY KEY,
    value TEXT NOT NULL
);
INSERT INTO agent_settings (key, value) VALUES
    ('wake_phrase',          'EchoAI'),
    ('voice_mode',           'chat_only'),
    ('tts_enabled',          'false'),
    ('history_limit',        '500'),
    ('allowed_paths',        '[]'),
    ('overlay_start_visible','false')
ON CONFLICT (key) DO NOTHING;

-- ─── 010/011 settings ────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS trial_meta (
    id           BIGINT PRIMARY KEY CHECK (id = 1),
    install_date TEXT NOT NULL
);
INSERT INTO db_config (key, value) VALUES ('gpu_enabled', '1') ON CONFLICT (key) DO NOTHING;

-- ─── 012 meetings ────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS meetings (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title        TEXT NOT NULL,
    started_at   TEXT NOT NULL,
    ended_at     TEXT,
    language     TEXT NOT NULL,
    model_path   TEXT NOT NULL,
    status       TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','stopped','error')),
    error        TEXT
);

CREATE TABLE IF NOT EXISTS meeting_segments (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    meeting_id   BIGINT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,
    t0_ms        BIGINT NOT NULL,
    t1_ms        BIGINT NOT NULL,
    text         TEXT NOT NULL,
    created_at   TEXT NOT NULL DEFAULT (now()::text)
);
CREATE INDEX IF NOT EXISTS idx_meeting_segments_meeting_id ON meeting_segments(meeting_id, t0_ms);

-- ─── 014/020 graph + legal IR ────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS graph_nodes (
    id            TEXT PRIMARY KEY,
    chunk_id      TEXT NOT NULL REFERENCES chunks(id),
    node_type     TEXT NOT NULL
                  CHECK (node_type IN ('document','part','chapter','article','clause','subclause')),
    citation      TEXT,
    metrics       TEXT,
    -- 020
    instrument_id TEXT,
    legal_path    TEXT,
    in_force      BIGINT NOT NULL DEFAULT 1,
    source_page   BIGINT
);
CREATE INDEX IF NOT EXISTS idx_graph_nodes_citation   ON graph_nodes(citation);
CREATE INDEX IF NOT EXISTS idx_graph_nodes_chunk      ON graph_nodes(chunk_id);
CREATE INDEX IF NOT EXISTS idx_graph_nodes_instrument ON graph_nodes(instrument_id);
CREATE INDEX IF NOT EXISTS idx_graph_nodes_legal_path ON graph_nodes(instrument_id, legal_path);

CREATE TABLE IF NOT EXISTS graph_edges (
    id         TEXT PRIMARY KEY,
    from_node  TEXT NOT NULL REFERENCES graph_nodes(id),
    to_node    TEXT NOT NULL REFERENCES graph_nodes(id),
    edge_type  TEXT NOT NULL CHECK (edge_type IN ('contains','cross_reference','non_obstante','amended_by')),
    weight     DOUBLE PRECISION NOT NULL DEFAULT 1.0
);
CREATE INDEX IF NOT EXISTS idx_graph_edges_from ON graph_edges(from_node, edge_type);
CREATE INDEX IF NOT EXISTS idx_graph_edges_to   ON graph_edges(to_node, edge_type);

CREATE TABLE IF NOT EXISTS amendment_events (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    node_id        TEXT NOT NULL REFERENCES graph_nodes(id) ON DELETE CASCADE,
    kind           TEXT NOT NULL CHECK (kind IN ('inserted','substituted','repealed','omitted')),
    by_instrument  TEXT NOT NULL,
    effective_date TEXT,
    source_page    BIGINT,
    raw_marker     TEXT
);
CREATE INDEX IF NOT EXISTS idx_amendment_events_node ON amendment_events(node_id);

CREATE TABLE IF NOT EXISTS legal_xrefs (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    src_node_id   TEXT NOT NULL REFERENCES graph_nodes(id) ON DELETE CASCADE,
    dst_node_id   TEXT NOT NULL REFERENCES graph_nodes(id) ON DELETE CASCADE,
    edge_kind     TEXT NOT NULL CHECK (edge_kind IN ('cites','implements','under','amends')),
    confidence    DOUBLE PRECISION NOT NULL DEFAULT 1.0,
    source_phrase TEXT
);
CREATE INDEX IF NOT EXISTS idx_legal_xrefs_src ON legal_xrefs(src_node_id, edge_kind);
CREATE INDEX IF NOT EXISTS idx_legal_xrefs_dst ON legal_xrefs(dst_node_id, edge_kind);

CREATE TABLE IF NOT EXISTS procedures (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    anchor_node_id  TEXT NOT NULL REFERENCES graph_nodes(id) ON DELETE CASCADE,
    process_name    TEXT NOT NULL,
    description     TEXT
);

CREATE TABLE IF NOT EXISTS procedure_steps (
    id                 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    procedure_id       BIGINT NOT NULL REFERENCES procedures(id) ON DELETE CASCADE,
    step_order         BIGINT NOT NULL,
    actor              TEXT NOT NULL,
    action             TEXT NOT NULL,
    condition          TEXT,
    branch_of_step_id  BIGINT REFERENCES procedure_steps(id),
    timeline           TEXT,
    source_node_id     TEXT NOT NULL REFERENCES graph_nodes(id)
);
CREATE INDEX IF NOT EXISTS idx_procedure_steps_proc ON procedure_steps(procedure_id, step_order);

-- ─── 018/019 IR importer ─────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS ir_cache_index (
    sha256                  TEXT PRIMARY KEY,
    schema_version          BIGINT NOT NULL,
    doc_type                TEXT NOT NULL,
    nodes_total             BIGINT NOT NULL,
    nodes_ok                BIGINT NOT NULL,
    nodes_low_confidence    BIGINT NOT NULL,
    nodes_user_repaired     BIGINT NOT NULL DEFAULT 0,
    quality_score           DOUBLE PRECISION NOT NULL,
    orphaned_at             BIGINT,
    created_at              BIGINT NOT NULL,
    updated_at              BIGINT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_ir_cache_orphaned ON ir_cache_index(orphaned_at) WHERE orphaned_at IS NOT NULL;

CREATE TABLE IF NOT EXISTS ir_repair_log (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    source_id       TEXT NOT NULL,
    sha256          TEXT NOT NULL,
    node_id         TEXT NOT NULL,
    action          TEXT NOT NULL,
    before_text     TEXT,
    after_text      TEXT,
    repaired_at     BIGINT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_ir_repair_source ON ir_repair_log(source_id);
CREATE INDEX IF NOT EXISTS idx_ir_repair_sha    ON ir_repair_log(sha256);

CREATE TABLE IF NOT EXISTS doc_ir_progress (
    source_id       TEXT PRIMARY KEY,
    source_sha256   TEXT NOT NULL,
    doc_type        TEXT NOT NULL,
    total_chunks    BIGINT NOT NULL,
    next_chunk_idx  BIGINT NOT NULL,
    id_counter      BIGINT NOT NULL,
    nodes_json      TEXT NOT NULL,
    updated_at      BIGINT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_doc_ir_progress_sha ON doc_ir_progress(source_sha256);

-- ─── 021–025 drafting ────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS template_schema (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name             TEXT NOT NULL,
    instrument_type  TEXT NOT NULL CHECK (instrument_type IN ('summary','note')),
    source_format_ref TEXT,
    created_at       TEXT NOT NULL,
    updated_at       TEXT NOT NULL,
    UNIQUE (instrument_type, name)
);

CREATE TABLE IF NOT EXISTS template_slot (
    id                       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    template_id              BIGINT NOT NULL REFERENCES template_schema(id) ON DELETE CASCADE,
    ordering                 BIGINT NOT NULL,
    kind                     TEXT NOT NULL CHECK (kind IN ('boilerplate','cited','prose')),
    label                    TEXT,
    boilerplate_text         TEXT,
    required_source_category TEXT,
    prose_guidance           TEXT,
    provision_ref            TEXT,        -- 024
    UNIQUE (template_id, ordering)
);
CREATE INDEX IF NOT EXISTS idx_template_slot_template ON template_slot(template_id);

CREATE TABLE IF NOT EXISTS gold_example (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    template_id      BIGINT REFERENCES template_schema(id) ON DELETE SET NULL,
    instrument_type  TEXT NOT NULL CHECK (instrument_type IN ('summary','note')),
    content_ref      TEXT NOT NULL,
    created_at       TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS draft_session (
    draft_id    TEXT PRIMARY KEY,
    state_json  TEXT NOT NULL,
    finalized   BIGINT NOT NULL DEFAULT 0,
    created_at  TEXT NOT NULL,
    updated_at  TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_draft_session_finalized ON draft_session(finalized);

CREATE TABLE IF NOT EXISTS chat_message (
    id                TEXT PRIMARY KEY,
    draft_session_id  TEXT NOT NULL,
    seq               BIGINT NOT NULL,
    role              TEXT NOT NULL,
    content           TEXT NOT NULL,
    token_count       BIGINT,
    summarized        BIGINT NOT NULL DEFAULT 0,
    created_at        TEXT NOT NULL,
    UNIQUE (draft_session_id, seq)
);
CREATE INDEX IF NOT EXISTS idx_chat_message_session ON chat_message(draft_session_id, seq);

CREATE TABLE IF NOT EXISTS conversation_summary (
    draft_session_id  TEXT PRIMARY KEY,
    summary_text      TEXT NOT NULL,
    covers_upto_seq   BIGINT NOT NULL,
    updated_at        TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS one_ask_session (
    draft_id    TEXT PRIMARY KEY,
    state_json  TEXT NOT NULL,
    updated_at  TEXT NOT NULL
);

-- ─── schema version marker (parity with SQLite TARGET_SCHEMA_VERSION) ────────
INSERT INTO db_config (key, value) VALUES ('schema_version', '16')
ON CONFLICT (key) DO UPDATE SET value = excluded.value;
